/* From Uiverse.io by Mike11jr - Tags: loader */
.__UIV_SCOPE__ .spinner {
 width: 60px;
 height: 60px;
 position: relative;
}

.__UIV_SCOPE__ .spinner .dot {
 position: absolute;
 inset: 0;
 display: flex;
 justify-content: center;
}

.__UIV_SCOPE__ .spinner .dot::after {
 content: "";
 width: 7px;
 height: 7px;
 border-radius: 50%;
 background-color: rgb(12, 180, 231);
}

@keyframes spin {
 to {
  transform: rotate(360deg);
 }
}

.__UIV_SCOPE__ .spinner .dot {
 animation: spin 2s infinite;
}

.__UIV_SCOPE__ .spinner .dot:nth-child(2) {
 animation-delay: 100ms;
}

.__UIV_SCOPE__ .spinner .dot:nth-child(3) {
 animation-delay: 200ms;
}

.__UIV_SCOPE__ .spinner .dot:nth-child(4) {
 animation-delay: 300ms;
}

.__UIV_SCOPE__ .spinner .dot:nth-child(5) {
 animation-delay: 400ms;
}
